import json
from src.nodes.base import BaseNode
from src.runtime import houdini_runtime
from src.runtime.transaction_manager import get_transaction_manager
from src.runtime.validation_engine import get_validation_engine
from src.runtime.scene_cache import get_scene_cache

class HouMCPReplayTransactionNode(BaseNode):
    name = "hou_mcp_replay_transaction"
    category = "Houdini"

    def __init__(self):
        super().__init__()
        self.icon_path = "icons/houdini_icon.png"
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("transaction_id",   "string", widget_type="text", default="")
        self.add_input("dry_run",          "bool",   widget_type="bool", default=False)
        self.add_input("rollback_on_error","bool",   widget_type="bool", default=True)
        self.add_output("replayed",            "bool")
        self.add_output("operations_executed", "list")
        self.add_output("errors",              "list")
        self.add_output("graph_diff",          "any")
        self.add_output("status",              "string")
        self.add_output("report_json",         "string")
        # [AUTO-GENERATED-PORTS-END]

    def _fail(self, error, status="failed"):
        empty_diff = {
            "created": [], "deleted": [], "modified": [],
            "cooked": [], "connections_changed": [], "flags_changed": [],
        }
        report = {
            "status": status, "replayed": False,
            "operations_executed": [], "errors": [error],
            "graph_diff": empty_diff,
        }
        return {
            "replayed": False, "operations_executed": [], "errors": [error],
            "graph_diff": empty_diff, "status": status,
            "report_json": json.dumps(report, indent=2, sort_keys=True, default=str),
            "exec_out": True,
        }

    async def execute(self, inputs):
        txn_id = (inputs.get("transaction_id") or "").strip()
        dry_run = bool(inputs.get("dry_run", False))
        rollback_on_error = bool(inputs.get("rollback_on_error", True))

        if not txn_id:
            self.log_error("transaction_id is required")
            return self._fail("transaction_id is required")

        mgr = get_transaction_manager()
        stored = await mgr.get_transaction(txn_id)
        if stored is None:
            self.log_error(f"Transaction not found: {txn_id}")
            return self._fail(f"transaction not found: {txn_id}")

        operations = [
            op.get("params") or {"op": op.get("op")}
            for op in stored.get("operations") or []
            if op.get("op")
        ]
        # Ensure each op dict has the 'op' field from its parent record
        raw_ops = stored.get("operations") or []
        operations = []
        for rec in raw_ops:
            op_type = rec.get("op", "")
            if not op_type:
                continue
            params = dict(rec.get("params") or {})
            params["op"] = op_type
            operations.append(params)

        if not operations:
            self.log_info(f"Transaction {txn_id} has no operations to replay")
            empty_diff = {
                "created": [], "deleted": [], "modified": [],
                "cooked": [], "connections_changed": [], "flags_changed": [],
            }
            report = {
                "status": "replayed", "replayed": True,
                "operations_executed": [], "errors": [], "graph_diff": empty_diff,
            }
            return {
                "replayed": True, "operations_executed": [], "errors": [],
                "graph_diff": empty_diff, "status": "replayed",
                "report_json": json.dumps(report, indent=2, sort_keys=True, default=str),
                "exec_out": True,
            }

        # --- Validate all ops before any execution ---
        engine = get_validation_engine()
        validation = await engine.validate_operations(operations)
        if not validation["valid"]:
            errors = [
                f"[{e['op']}@{e['index']}] {e['message']}" for e in validation["errors"]
            ]
            self.log_error(f"Replay validation failed: {len(errors)} error(s)")
            empty_diff = {
                "created": [], "deleted": [], "modified": [],
                "cooked": [], "connections_changed": [], "flags_changed": [],
            }
            report = {
                "status": "failed", "replayed": False,
                "operations_executed": [], "errors": errors, "graph_diff": empty_diff,
            }
            return {
                "replayed": False, "operations_executed": [], "errors": errors,
                "graph_diff": empty_diff, "status": "failed",
                "report_json": json.dumps(report, indent=2, sort_keys=True, default=str),
                "exec_out": True,
            }

        if dry_run:
            warnings = [
                f"[{w['op']}@{w['index']}] {w['message']}" for w in validation["warnings"]
            ]
            self.log_info(
                f"dry_run: {len(operations)} op(s) from transaction {txn_id} validated"
            )
            empty_diff = {
                "created": [], "deleted": [], "modified": [],
                "cooked": [], "connections_changed": [], "flags_changed": [],
            }
            report = {
                "status": "validated", "replayed": False,
                "operations_executed": [], "errors": [], "graph_diff": empty_diff,
                "warnings": warnings,
            }
            return {
                "replayed": False, "operations_executed": [], "errors": warnings,
                "graph_diff": empty_diff, "status": "validated",
                "report_json": json.dumps(report, indent=2, sort_keys=True, default=str),
                "exec_out": True,
            }

        # --- Execute ops in order ---
        cache = get_scene_cache()
        cache.clear_dirty_state()

        # Begin a new transaction for the replay
        replay_name = f"replay_{txn_id[:8]}"
        try:
            new_txn_id = await mgr.begin_transaction(replay_name, metadata={"source_txn_id": txn_id})
        except Exception as exc:
            self.log_error(f"begin_transaction failed: {exc}")
            return self._fail(f"begin_transaction failed: {exc}")

        executed = []
        first_error = None

        for i, op in enumerate(operations):
            recorded = await houdini_runtime.execute_operation(op)
            try:
                await mgr.record_operation(new_txn_id, recorded)
            except Exception as exc:
                first_error = f"record_operation failed at index {i}: {exc}"
                break
            executed.append({
                "index": i, "op": recorded.get("op"), "status": recorded.get("status")
            })
            if recorded.get("status") == "failed":
                first_error = recorded.get("error") or f"op '{recorded.get('op')}' failed"
                self.log_error(f"Replay op {i} failed: {first_error}")
                break

        rollback_performed = False
        rollback_errors = []
        if first_error is not None:
            if rollback_on_error:
                try:
                    result = await mgr.rollback_transaction(new_txn_id)
                    rollback_performed = True
                    rollback_errors = result.get("rollback_errors") or []
                except Exception as exc:
                    rollback_errors = [{"op": "<rollback>", "error": str(exc)}]
                    try:
                        await mgr.mark_failed(new_txn_id, str(exc))
                    except Exception:
                        pass
            else:
                try:
                    await mgr.mark_failed(new_txn_id, first_error)
                except Exception:
                    pass
        else:
            try:
                await mgr.commit_transaction(new_txn_id)
            except Exception as exc:
                self.log_error(f"commit_transaction failed: {exc}")

        final = await mgr.get_transaction(new_txn_id) or {}
        diff = cache.get_dirty_nodes()
        all_errors = list(final.get("errors") or [])
        if rollback_errors:
            all_errors.extend(rollback_errors)

        status = final.get("status", "failed")
        replayed = status == "committed"

        if replayed:
            self.log_success(
                f"Replayed transaction {txn_id!r} → {new_txn_id!r} "
                f"({len(executed)} op(s))."
            )
        elif status == "rolled_back":
            self.log_info(f"Replay rolled back after error: {first_error}")
        else:
            self.log_error(f"Replay failed: {first_error}")

        report = {
            "status": status, "replayed": replayed,
            "source_transaction_id": txn_id,
            "new_transaction_id": new_txn_id,
            "operations_executed": executed,
            "errors": all_errors, "graph_diff": diff,
        }
        return {
            "replayed": replayed,
            "operations_executed": executed,
            "errors": all_errors,
            "graph_diff": diff,
            "status": status,
            "report_json": json.dumps(report, indent=2, sort_keys=True, default=str),
            "exec_out": True,
        }

def register_node():
    return HouMCPReplayTransactionNode
